INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Назри обориро дар муайян кардани ҳосилнокии сир</h2><p>Сир (Allium sativum) ҳамчун яке аз кӯҳантарин сабззавоти ароматӣ ва дорӣ дар бозорҳои кӯҳназарии дохилӣ ва хориҷӣ мақоми махсус дорад. Муваффақият дар парвариши ин маҳсулот ба фаҳмиши амиқ аз ниёзҳои решаҳо ва физиологӣи растани вобаста аст. яке аз масъалаҳои асосии деҳқонон дар минтаҳаҳои хушк ва ним-хушк, идоракунии мувофиқи захираҳои обӣ мебошад. Усулҳои анъанавии обориро, ба монанди обдорӣ, одатан боиси парокандагии шадиди об, намакии хок ва баъзан фароғунии решаҳо мегарданд. Баръакс, системҳои муосири оборирои бӯрида, бо махсуси <strong>нӯриб тайп</strong>як ҳалли дақиқ ва самаранок барои расидан ба ҳадакландан кардани ҳосилнокии сир дар ҳектарро пешниҳод мекунанд. Нӯриб тайп тавассути паҳн кардани паст-фишор ва якхелаи об дар соҳаи решаҳо, имкони идоракунии дақиқи таркиби намро фароҳам меорад, ки таъсири мустақиме дар ташаккул ва шинобии сириҳо дар зери замин дорад.</p><h2>Механизми кори нӯриб тайп ва таъсири он ба рушди сир</h2><p>Нӯриб тайп як ҷурти лӯлаи польетилени назок бо сӯрохҳои микроноӣ аст, ки одатан ба таври мундиршаванда ё дар сатҳи хок дар узунҳои сафҳои нишон гузошта мешавад. Ин система бо фишори паст обро ба қатраҳои майда табдил дода, онҳоро наздики решаҳо паҳн мекунад. Барои растании сир, ин усул идеалӣ аст, зеро решаҳои сир сатҳии мебошанд ва чуқурӣи кам доранд. Истифодаи нӯриб тайп боиси нигоҳ доштани намкӣ дар қабатҳои болоии хок мешавад, дар ҳоле ки аз пуршудани хок ва коҳиши оксиген дар соҳаи реша пешгирӣ мекунад. Оксигении кофӣ барои нафаскашии решаҳо, омили ҳаётии дар ҷабҳи моддаҳои ғизоӣ ва интиқоли моддаҳои органикӣ аст, ки боиси шинобии бештари сириҳо мегардад. Инчунин, тақсимоти якхелаи ҳарорат дар атрофи решаҳо, стресси гармииро кам мекунад, ки оид ба рушди якхелаи пайвастҳо ва коҳиши хамшудагии сир мусобида мекунад. Ин якхелагии дар рушд, мустақиман боиси зиёдшудани муқовимати ҳосилдохтӣ ва беҳбудии сифати тиҷорати маҳсулот мегард.</p><h3>Фойдаҳои асосии истифодаи наворпайро баҳс сар</h3><ul><li><strong>Ҷоҳеъҷоии манбаъҳои обӣ:</strong> Наворпай бо кам кардани буғшавии мустақим аз сатҳи хок метавонад истеъмолро то 40 фоиз нисбат ба обӣҳои анъанавӣ кам кунад, дар ҳоле ки намнокӣ зарурӣ барои решаҳо комилан таъмин мешавад.</li><li><strong>Кам кардани гилҳаи:</strong> Чунки намнокӣ танҳо дар наворҳои таркиши дар атрофи гиёҳ нигоҳ дошта мешавад, гилҳаҳои байни сатҳҳо бо норасоии об муhofot мешаванд ва рақобат барои манбаъҳо кам мешавад.</li><li><strong>Имкони ғизодории дақиқтар:</strong> Яке аз фойдаҳои муҳими наворпай қобилияти фертисатсия (Fertigation) мебошад. Бо зангидани маҳалли ғизоҳои суръати баланди нақли моддаҳои ғизоӣ ба решаҳои сатҳии сарсофӣ имконпазир мешавад.</li><li><strong>Беҳтар кардани сифати сафолӣ:</strong> Хаммагарии нисбии сатҳи замини байни маротибаҳои овардани об ба тӯрҳо имкон медиҳад, ки пиёзоҳо мустаҳкамтар шаванд ва хираи барвақтро пешгирӣ кунанд.</li></ul><h2>Стратегияҳои амалӣ барои беҳтар кардани иригацияи қатторӣ дар боғҳои пиёз</h2><p>Барои ба даст овардани беҳтарин ҳосили пиёз дар ҳектаор бо усули қатторӣ, танҳо насби система кофӣ нест; балки танзимотҳои дақиқи техникӣ ва кишоварзӣ муҳимияти ҳаётӣ доранд. Дар зери ин сарлавҳа, мо параметрҳои самаранокро ҷанба ба ҷанба месанҷем.</p><h3>Интихоби материал ва қаллодии мувофиқи қаттори иригация</h3><p>Домдории қаттори иригация дар тӯли мавсими кишт ва ҳатто барои солҳои оянда ба материал ва қаллодии девори лӯлҳои оббарӣ вобаста аст. Лӯлҳои хеле нарм (паст аз 0.2 миллиметр) эҳтимоли зарардиҳии ҳайвонот ва офтобро доранд. Аммо лӯлҳои хеле қаллоп имкон медиҳад, ки хароҷотҳои ибтидоӣ зиёд шуда, суръати баромадани об аз сӯрохҳо паст шавад. Барои пиёз, лӯлҳо бо қаллодии миёна (0.3 то 0.4 миллиметр) бо сӯрохҳои микронӣ (0.4 то 0.8 миллиметр) тавсия дода мешаванд, то мувозинат байни домдорӣ ва суръати паҳншавии об нигоҳ дошта шавад. Ҳамчунин, истифодаи лӯлҳои муқобилат ба хиракуна (Anti-clog) барои пешгирии пӯшидани сӯрохҳо бо олаву чормағз, бисёр муҳим аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-سیر-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت سیر در هکتار با نوار تیپ - تصویر 1"/><figcaption>ҳосилии кишоварзӣ дар ҳектаор иригацияи қатторӣ пиёз</figcaption></figure><h3>Муайян кардани фосилаи дурусти қаттори иригация</h3><p>Фосилаи тасмаи оварӣ аз қатори гирифтани сарсоқ, параметри ҳассос аст. Агар тасма хеле наздик ба сабути сарсоқ ҷойгир бошад, намӣи баланди сабут овардабарори афзоиши қоғозҳо ва бемориҳои барг-фруктро мекунад. Агар хеле дур бошад, решаҳои сатҳӣ мушкилоти камобии об мебинанд. Одатан фосилаи 5 то 8 сантиметр аз маркази қатори гирифтани, нуқтаи оптималӣ аст. Фосилаи тасмаи оварӣ дар чогои шакар ҳам принсипҳои монанд дорад, аммо барои сарсоқ ба сабаби ҳассосияти бештар ба намии иловагии пӯст, эҳтиёти бештар лозим аст. Кўрҷӗ бо санҷишҳои обсанҷӣ, соҳаи таъсирот (Wetted Area)-ро дар хокши мутанаввис муайян кунад ва фосилагузориро дар асоси он танзим намояд.</p><h3>Барномагузории оварӣ дар асоси марҳилаҳои рушди сарсоқ</h3><p>Ниёзи оварии сарсоқ дар тӯли фасли рушд доимӣ нест ва бояд тавассути тасмаи оварӣ танзим карда шавад:</p><ol><li><strong>Давраи аввали навсозӣ:</strong> Дар ин марҳила, об ба миқдори кам вале мунтазам (ҳар 2 то 3 рӯз) барои навбудӣ ва решаи ҳосил шудан лозим аст.</li><li><strong>Давраи рушди фаъол:</strong> Бо калон шудани баргҳо, ниёз ба об афзуда мешавад. Тасмаи оварӣ бояд чунон танзим карда шавад, ки намӣи реша дар сатҳи оптималӣ бомад.</li><li><strong>Давраи ҳосилшудагӣ:</strong> Тақрибан 3 то 4 ҳафтаи аввал аз омодагӣ, барномаи обориро бояд тадриҷан кам кард. Обории зиёд дар ин марҳила ба сабуки шудани попу ва кам шудани мутаҳидии маҳсул оварда мерасонад. Навари тиб ба фермер имконият медиҳад, ки кам шудани тадриҷиро дақиқ рабита кунд.</li></ol><h2>Муқоисаи иқтисодӣ ва самаранокии навари тиб нисбат ба усулҳои дигар</h2><p>Таҳлили иқтисодӣ нишон медиҳад, ки гарчанде ки хароҷоти асосии насби нварии тиб аз хоки хоси унвонӣ баландтар аст, вале баргашти сармоя аз тавассути зиёд шудани маҳсулот ва кам шудани хароҷоти қувваи корӣ ва об, дар ояндаи дур бисёр муфид аст. Дар муқоиса бо обории мофӣ, навари тиб ба рушди якхелаи рахиҳо дар тамоми заргир оварда мерасонад. Модирони нварии тиб танҳо ба муҳаррики помп ва таймер ниёз доранд ва ниёз ба ханҷокунии арсаҳо барои ободро аз байн мебарорад. Ин таҷҳизот инчунин имконияти иҷрои мувоҷидии обод ва ханҷоки (Fertigation) -ро медиҳад, ки истеҳсоли моддаҳо мисли фосфат ва потассий, ки дар ҳосилии сӯроп муҳим мебошанд, -ро ба таври фаъол зиёд мекунад. Фермерон метавонанд бо таъсиркунии нварии тиб бо партоби муносиби хок, таъсироти мусбатро чандкаратаз кунанд.</p><h3>Мушкилоти маъмулӣ ва ҳалҳои техникӣ</h3><p>Дар амал, баъзе мушкилоти метавонанд таъсири нварии тибро кам кунанд. Хирашавии сӯробҳо (Clogging) мушкилоти маъмултарин аст. Барои пешгирии ин мушкилӣ, истифодаи партобкунандаҳои дуқатъаӣ (моллӣ ва сӯроб) тавсия меравад. Инчунин, насби нварӣ дар сатҳи UV ва ҳарорати баланд боиси вайроншавии полимеди мебошад. Беҳтар аст, ки навариҳо бо иҳтиёт дар хок (дар чуқурии 2 то 3 сантиметр) ҷойгир кунанд, то ҳам аз зарари физикӣ ва ҳам аз шикастани ҳароратӣ пешгирӣ шавад. Инчунин, фишори корӣи таҷҳизот бояд мувофиқати дарозии навари танзим шавад, то аз паршавии ноҳамои об дар ифтодагии хат пешгирӣ карда шавад. Истифодаи вентили таъсири фишор дар ифтудаги ҳар хат кафолат медиҳад, ки рахиҳои ифтудаги хат низ ҳадди зарурати об од карда мешаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-سیر-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت سیر در هکتار با نوار تیپ - تصویر 2"/><figcaption>бодиҳоди партобод бар қирӯз дорад дар асоси таҳияи қувваи сир ва усули нуткиш</figcaption></figure><h2>Саволҳои маъмул (FAQ) дар бораи нуткиши чунин ва сир</h2><p><strong>1. Оё нуткиши чунин барои ҳамаи намудҳои сир мувофиқ аст?</strong><br>Бале, аммо таваққуф ва ҳаҷми обӣ бояд мувофиқи иқлим ва навъи сир (сир кӯчак ё калон) танзим карда шавад. Сирҳои маҳаллӣ, ки ба камобӣ тобоваранд, бо миқдори камтар осеб намебинанд.</p>\n<p><strong>2. беҳтарин вақти насби нуткиши чунин дар ҳангоми коркарди сир кадом аст?</strong><br>Беҳтарин вақт, ҳамзамон бо паҳни сир аст. Насби нутк пеш аз паҳн имконияти танзими дақиқ масофаи нутк аз ниҳолро фароҳам меорад ва осеб ба решаҳои ҷавонро кам мекунад.</p><p><strong>3. чӣ тавр метавонам аз пӯшидани сӯрохиҳои нуткиши чунин пешгирӣ кунам?</strong><br>Истифодаи системаи дуқабатаи тозакунии об, шустушёи ибтидоии система пеш аз пайваст ба помпа ва истифодаи оби хушсифат (бо тарҷих оби тоза) зарур аст. Инчунин, шустушёи мунтазами система дар охири мавсум тавсия мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-سیر-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت سیر در هکتار با نوار تیپ - تصویر 3"/><figcaption>Бародиёрии ҳосили сармоя ба ҳар гектар, обории қатқатӣ, сармоя</figcaption></figure><p><strong>4. Қатқатӣ (дроп) дар муқобили барон, кадом барои сармоя беҳтар аст?</strong><br>Дар деҳот бо баронҳои нопурра ва кам, обории қатқатӣ бартарии мутлақ дорад, зеро имконияти идоракунии дақиқи намдориро фароҳам меорад. Дар минтаҳаҳои баронсоз, комбинасияи обори қатқатӣ бо системаи мувофиқи дрениратсия беҳтарин вариант аст, то аз намакиндии хок пешгирии шавад.</p>\n<h2>Хулоса ва тавсияҳои охирин</h2><p>Қарори истифодаи обори қатқатӣ барои зиёд намудани ҳосили сармоя дар як гектар қадами муҳим ба сӯи кишоварзии муосир ва устувор аст. Ин система бо таъмини обори дақиқ, кам кардани стресси решаҳо ва имкони пухтаншиди самараноки маводи корӣ, имконияти офтаги ҳосили сармояро ба ҳадди аввал мебарорад. Бо риояи принсипҳои насб, интихоби ғафсии мувофиқ ва пайравӣ ба барномаи аввали обори даҳӣ, деҳқон на танҳо ҳосили вазнавии худро зиёд карда метавонад, балки сифати тиҷорати сармояро низ беҳтар менамояд. Тавсия мешавад, ки пеш аз иҷрои васеъ, озмоиши хурд дар қисми мезроб анҷом шавад, то тобшавӣи техникӣ дар низоми обори қатқатӣ ба шароити махсуси хок ва иқлими минтақа мутобиқ кунод. Дар охир, комбинатсияи дониши техникӣ обори бо идоракунии дурусти кишоварзӣ, калиди дастёби максимум самараноки ва фоиданокӣ дар парҳези сармоя аст. Тавассути нигоҳдорӣ ва идоракунии дурусти системаи обори қатқатӣ, умри кории системаро зиёд карда, сарфиёди корӣро соли солӣ идора кардан мумкин аст.</p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%86%DA%AF%D9%87%D8%AF%D8%A7%D8%B1%DB%8C-%D9%88-%D9%85%D8%AF%DB%8C%D8%B1%DB%8C%D8%AA-%D9%86%D9%88%D8%A7%D8%B1-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D8%AA%DB%8C%D9%BE/">D986DAAFD987D8AFD8A7D8B1DB8C D988 D985D8AFDB8CD8B1DB8CD8AA D986D988D8A7D8B1 D8A2D8A8DB8CD8A7D8B1DB8C D8AADB8CD9BE</a>, <a href="https://navar-abyari.ir/mikdori-tukhmi-shimo-dar-yak-gektar/">mikdori tukhmi shimo dar yak gektar</a>, <a href="https://navar-abyari.ir/%d9%81%d8%a7%d8%b5%d9%84%d9%87-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%af%d8%b1-%da%86%d8%ba%d9%86%d8%af%d8%b1-%d9%82%d9%86%d8%af-%d8%a8%d9%87%d8%aa%d8%b1%db%8c%d9%86/">Фосилаи нӯҳурҳои тасмими стандартҳои тавсияшуда барои чунганди ширин</a>, <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D9%86%D8%AE%D9%88%D8%AF-%D9%81%D8%B1%D9%86%DA%AF%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 D986D8AED988D8AF D981D8B1D986DAAFDB8C D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Гардиши пурраи афзун кардани ҳосили сирбаро дар як гектар бо истифода аз системаи ниппленд','Сармо яке аз маҳсулотест, ки арзиши иқтисодӣ дорад ва ороиш мувофиқ нақши калидиро дар муайян кардани андозаи ниҳоии ғалатаи сармо дар як гектар боз мекунад. Дар ин матн мо мебаррасем, ки истифодаи дурусти системаи ороиши бозаркунанда (drip irrigation) чӣ тавр бо кам шудани дониши обӣ ва тақсимоти якхелаи ботнок, боиси зиёд шудани назарраси самаранокӣ ва сифати маҳсулоти сармо мегардад.','publish','closed','closed','guide-to-increase-garper-hectare-with-tube-drip',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
