INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على أفضل ممارسات زراعة البطيخ باستخدام تقنية الري بالتنقيط. دليل عملي يغطي التخطيط والري والعناية الشاملة لضمان موسم حصاد غزير وإنتاجية مثالية للمزارع العراقي.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
