INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мактаби кӯдаконии малавҳо, мо усулҳои парвариши малав бо оборӣи қатравиро омӯзему мекушоем. Дар ин ҷо мо метавонем ба шакли пурраи малавҳо, таъсир ба мусоиди муҳити зист ва ҳуҷраҳои намоишӣ, аз ҷумла, ҷоҳи малавҳо, ҷоҳи ғалғорӣ ва намоишҳои ғализ, ҷоҳи мулоим ва намоишҳои ғализ.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
