INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على مقدار محصول القصب في الدّون باستخدام نظام الريّ بالتنقيط (تيب)، مع استراتيجيات عملية لزيادة العائد الإنتاجي وتحسين كفاءة استهلاك المياه للمزارع في العراق.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
