INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Навҳои (Теп) боббона ба далели арзиши пастии насбкунӣ ва анعطэффъи баланд, дар солҳои охир ҷойи системаҳои доими чоридаро гирфанд. Аммо оварии асосии ин системаҳо, ҳассасии аслии онҳо ба муқаддама ва дивор мебошад. нигоҳдории нави боббона раванди пайваста аст, ки оғози он аз тарҳии ибтидоии системаи ниҳоӣ шурӯъ шуда, то вақте ки навҳо дар охири фасл дар замин ҷамъ шуда ва дар анбор интиқол дода шаванд, давом мекунад. Бисёри оваронон бовар доранд, ки нави боббона як маҳсули истеъмолӣ як маротиба будан аст, аммо бо риояи принсипҳои имнияву техникии, метавон аз ин навҳо то 3 ё 4 сол бо сифати қабулшаванда истифода бурд. Дар зери, мо муҳимоти техникии ва нуқтаҳои тиллоии муҳофизат аз сӯрохҳои хурд ва бадани навро баррасӣ мекунем.</p>\n<h2>Баррасии сохтор ва вобастагии навҳои (Теп)</h2>\n<p>Хилфи чоридарҳои полимерӣ, ки каналҳои дохилии мураккаб доранд, нави боббона аз як лӯлаи хулк (шуъораи 16 ё 19 миллиметр) бо сӯрохҳои перфоратсия (1 то 3 миллиметр) ташкил шудааст. Ин сӯрохҳо бевосита бо муҳити берунӣ (хак) дар тамос мебошанд. Бинобар ин, ҳар як зарраи гилл, қабати калсийӣ, ё ҳатто зобҳои микробӣ метавонад роҳи обро бастандакунӣ кунанд. <a href="https://navar-abyari.ir/nuqtahoi-muhim-hangomi-istifodai-lundahoi-tipisi-baroi-obyori/">Нуқтаҳои муҳим ҳангоми истифодаи нави (Теп) барои обкорӣ</a> Дар бар гирифтани шиносоии дақиқи манбаъҳои оварии об мебошад. Агар манбаи оби шумо сатҳӣ (қанот ё канал) бошад, хавфи диворотики чанд маротиба зиёдтар аз оби чолоқ аст. Дар ин ҳолат, филтрҳои торакии тозакунавӣ бо ягона наёфтанд, ва бояд аз филтрҳои расадантии (шакли дона) ё филтрҳои дискӣ/шакли канор истифода бурд, то зарраҳои мутакариб пеш аз ворид шудан ба нави отҳоло шаванд.</p>\n<h3>Таъсири фишор ба умри нав</h3>\n<p>Феҳшоб як омил муайянкунанда дар нигоҳдории нақбчаҳои чӯбӣ мебошад. Агар феҳш аз ҳадди истинод зиёд бошад, сӯрохҳои перфоративӣ зери таъсири қувваи гидравликӣ қарор мегиранд ва бо гузашти вақт кашида мешаванд ва шакли худро аз даст медиҳанд. Ин падида боиси шудани нақши нифоки оби ғайрисимметрӣ ва пурра пӯшидани баъзе сӯрохҳо мегардад. Маслиҳати ихтисосӣ ин аст, ки феҳши кории системаи нақбчаҳои чӯбӣ одатан бояд байни 1 то 2 бар нигоҳ дошта шавад. Истифодаи ширҳои танзими феҳш дар чораки ҳар нақбча (ё чораки лӯлаи асосӣ) барои пешгирии лағзишҳои феҳшии аз ҳисоби помпҳои прессистативӣ зарур аст. Инчунин, <a href="https://navar-abyari.ir/%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%DA%A9%D8%B4%D8%A7%D9%88%D8%B1%D8%B2%DB%8C/">Пайвастҳои нақбчаҳои чӯбӣ барои кишоварзӣ</a> бояд аз полимери полиэтилен бо шакли T (Tee) ё куплинги (Coupling) истифода шаванд, зеро пайвастҳои лӯлавӣ ё бандуқҳои металлӣ дар мӯҳлати дароз оташи механикӣ ва рамакии дар нуқоти ҳосистаро ба вуҷуд меоваранд.</p>\n\n<h2>Стратегияҳои шӯи бемонимат система</h2>\n<p>Қисми муҳимтарини нигоҳдории нақбчаҳои чӯбӣ, иҷрои шӯи дуруст дар оғоз ва охирини ҳар давраи обёрӣ аст. Шӯ танҳо барои тозакунӣ нақбча нест, балки барои парокунандагии зарраҳои ашҷояшуда дар тӯли масири система мебошад. Азбаски нақбчаҳои чӯбӣ одатан бечизи нохияи хеле хурд доранд, ҷараёни об бояд чунин бошад, ки тавонӣ зарраҳои муаллифро бо худ берун орад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-شوید-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری شوید با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>crop drip tape maintenance care шавед</figcaption></figure>\n<h3>Шӯи оғозӣ (Flush-in)</h3>\n<p>Вақте ки шумо системаро барои бори аввал дар фасл мекушед, шумояд зарраҳои чӯбидо дар тораҳои филтрҳо ва нақбчаҳо боқимонда бошанд. Кушодани об барои 5 то 10 дақиқа бе феҳши баланд (ҳатто бо ширҳои ним кушода) имкон медиҳад, ки зарраҳои шиноанда ба самти барории система равона шаванд. Агар барории система шумо ба як наҳр ё гӯдак кушода бошад, ин зарраҳоро ҷамъ кунед, то аз дубора ворид шудани онҳо ба система пешгирӣ шавад.</p>\n<h3>Шустани андиша (Flush-out)</h3>\n<p>Пас аз оҳангии оборӣ, фишор бояд барои кушодани сӯрохҳои бастаҳо зиёд карда шавад. Вақти беҳтарин барои шустани андиша он аст, ки фишори помпа дар ҳадди максимум бошад ва кранҳои хуруҷии ҳамаи лентаҳо баста нашуда бошанд. Азбаски лентаҳо одатан дар андишаи хат кушода мебошанд, бо кушодани ҳамаи кранҳои андишагӣ ва нигоҳ доштани ҷараёни шиддатнок, об бо суръати баланд аз дохили лента гузашта, зарраҳои чоробро ба берун ҳал мекунад. Ин амал бояд ҳадди ақал 5 дақиқа идома ёбад. Иҷрои ин кор бо шакли мунтазам аз пайдо шудани қабатҳои часпандаи микробӣ дар деворҳои дохилии лентаҳо пешгирӣ мекунад.</p>\n<h2>Санитатсияи филтрасия ва хлоринатсия</h2>\n<p>Филтри ҷазобкунанда (Sifter) ё филтри асосӣ бояд ҳар ҳафта кушода ва шуста шавад. Дар системаҳои лентаии нӯри (tape), ҳар гуна нокосии филтрасия мустақиман ба баста шудани сӯрохҳои лентаҳо оварда мерасонад. Ғайр аз филтри механикӣ, истифодаи хлор ё гидроген пероксид барои санитатсии об тавсия дода мешавад. Хлор бо консентратсияи 1 то 2 миллиграмм дар як литр метавонад афзоиши бимоҳои биойфилмро (Biofilm), ки сабаби асосии баста шудани сӯрохҳои нарми лентаҳо аст, ихтиёр кунад. <a href="https://navar-abyari.ir/%D9%84%D9%88%D9%84%D9%87-%D9%86%D8%AE%DB%8C-2-%D8%A7%DB%8C%D9%86%DA%86/">Пайп аз матоъи абрӣ 2 дюйм</a> Ба сифати пайпи асосӣ дар бисёр системаҳои хурд истифода мешавад, аммо бояд ба назар гирифт, ки пайпҳои абрии дар тӯли муддат имконияти афзоиши биойфилмро дар ҷисми пайп доранд ва дар сурати дидани иваз шудани ранги об дар дохили пайп ба шустани кимиёвии шиддатнотар ниёз доранд.</p>\n\n<h2>Рӯйхати ҷамъ овардан ва захиравии лентаҳои нӯри (tape)</h2>\n<p>Яке аз ченориҳои бузург дар нигоҳдории лентаҳои нӯри, чӣ гуна ҷамъ овардани онҳо дар охиргирии фасл аст. Лентаҳои нӯри хеле нарманданд ва дар рӯи шафофи офтоб, бо суръат деградатсия меёбанд (таҳруби UV). Инчунин, агар лентаҳо дар ҳолати кушода ва пӯшида қарор гиранд, гардида (Twist) метавонанд, ки кушодани онҳо хеле мушкил аст ва эҳтимоли парешониро зиёд мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-شوید-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری شوید با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>Нигоҳубин ва таъмири ғалабонак</figcaption></figure>\n<h3>Техникаҳои дурусти пайвасти тӯбҳо</h3>\n<p>Пас аз бардоштани лентаро аз замин, онро дар ҷое мустаҳкам ва бе кашиш гузоред. Сипас бо истифода аз барабан (Drum) ё анборчаи пӯлӣ мувофиқ, лентаро бо эҳтиёт чархед. Суръати чархкунӣ бояд паст бошад, то лента зери фишор намонда, чуқуриҳо ғайритавъонӣ нашаванд. Пеш аз захирагирӣ, боварӣ ҳосил кунед, ки ҳамаи лентаҳо комилан хушканд.намнокӣ боиси паразитҳо ва ифлосшавии чуқуриҳо мешавад. Агар имкон дошта бошад, лентаро бо дастпӯшҳои мувофиқ барои гирифтани обангӯз ва чир аз рӯи сатҳи лента пеш аз чархидан тоза кунед.</p>\n<h3>Шароитҳои муносиби захирагирӣ</h2>\n<p>Лентабарҳои ғалабонак бояд дар муҳити торик, хушк ва ҳарорати мулоим нигоҳ дошта шаванд. Захирагирӣ дар гаражҳо ё анбарҳои кишоварӣ, ки аз чанг ва намнокӣ пешгирӣ мекунад, беҳтарин аст. Аз гузоштани лентабарҳо дар наздикии мустақими офтоб дар тобистон ё сармои шадид зимистон дурӣ кушед. Ҳамчунин, аз гузоштани ашёҳои вазнин болои тӯбҳои лентабарҳо пешгирӣ кунед, то фишори механикӣ ба бадани лентабар ворид нашуда бошад. Агар шумо дар фасли оянда аз лентабарҳо истифодаи дубора мекунед, пеш аз насб кардан онҳоро, як қисми 5-метраро аз оғози лентабар кушоед ва обро бо фишори баланд аз он гузаред, то боварӣ ҳосил кунед, ки пас аз нигоҳ доштани тӯлоии дароз, чуқуриҳо ифлос нашудаанд.</p>\n\n<h2>Таъсири намуди кунҷкунӣ ба нигоҳубунии система</h2>\n<p>Навъи растани ва роҳи кунҷкунӣ ба намунаи чангу обангӯз ва ворид шудани интиқолиҳо ба ғалабонак таъсир мерасонад. Дар кунҷкунӣҳои تابستانӣ, монанди помидор ё қаймоқ, агар аз тонелҳо истифода шавад, намнокии баланд ва нури офтоби кам, заминаро барои афзоиши сариъ миқробҳо ва вобадҳои дар дохили системаи обёрӣ фароҳ меорад. Бинобар ин, дар ин қисмҳо, шустани кимиёвии система бо кислотаи ситрукӣ ё хлор, аҳамияти дубора меёбад. <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%a8%d8%b1%d8%a7%db%8c-%da%a9%d8%af%d9%88/">Лентабари обёрӣ барои қаймоқ: Раҳнамудди умумии интихоб ва истифодабарӣ</a> Пешниҳуд карда мешавад, ки масофаи байни ҷорӣ ва пои растани ҳадди ақал 15 сантиметр бошад, то аз пӯшидани сӯробҳо тавассути баргҳои афтода ва мурч (Mulch) пешгирӣ карда шавад. Дар ғармонҳои тирамоҳ, бо гарм шудани ҳаво ва зиёд шудани фаъолиятҳои биологӣ, хатари пӯшидани биологӣ афзоиш меёбад. Дар ин фаслҳо, истифодаи моддаҳои зидди микробӣ дар об қисми ҷудонашавандаи барномаи нигоҳдории ҷориҳои ғарфонӣ мебошад.</p>\n<h2>Саволҳои маъмул дар бораи ҷориҳои ғарфонӣ</h2>\n<h3>Оё ҷориҳои ғарфониро тамир кардан мумкин аст?</h3>\n<p>Таъмири ҷориҳои ғарфонӣ бо усули ҷамъкунакӣ (масалан, часпоидани дорӣ) хеле душвор ва нодир аст, зеро бадани ҷорӣ одатан 1 миллиметр ғафс дорад ва часпандарҳои махсуси он дар дастрасии меъор надида мешаванд. Беҳтарин роҳ ҳимоя аст. Агар ҷорӣ дор шуд, кӯшиш накунед, ки онро кушоед; ба ҷои он, қисми онро бурида, бо пайвасткунаки нав дубора ба система пайваст кунед. Агар доршавӣҳо такрорӣ бошанд, ин аломати заифии дар системаи нигоҳдорӣ ё фишори но мувофиқ аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-شوید-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری شوید با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>нигоҳдории ҷориҳои ғарфонии партов барои партоҳии ҳашорот</figcaption></figure>\n<h3>Чанд бор дар сол бояд ҷориҳои ғарфониро иваз кунем?</h3>\n<p>Бо риояи асосҳои нигоҳдорӣ ва нигоҳ доштани дуруст, ҷориҳои ғарфонии сифатнок метавонанд 3 то 5 фасл давом кунанд. Ҳаёти кории ҷорӣ вобаста ба ҳаҷми истифода, навъи об ва дараҷаи хлоринатсия мебошад. Агар ҷори шумо дар оғози фасл дор шуд, ба ҷои иваз кардани тамоми қисм, метавонед аз қисмҳои солим барои системаҳои хурдтар ё хонаҳои шамъафшон истифода баред.</p>\n<h3>Оё фишори баланд ҳамеша бад аст?</h3>\n<p>Бале. Фишори баландтар аз 2.5 бар дар тасмаи одумона боиси кашидан сангҳо ва ноумедил будани оби партодан мешавад. Ҳамеша бошони фишор (Манометр) дар охироти тасма истифода баред то аз дараҷаи фишор дар баромад боварӣ ҳосил кунед. Агар фишор аз 2 бар баландтар бошад, вентилҳои асосӣ-ро каме пӯшед то фишор кам шавад.</p>\n<h2>Хулоса ва нуқтаҳои охирин</h2>\n<p>Нигоҳдорӣи тасмаи одумона як соҳибкорӣ аст, ки рост ба самаранокии маҳсулот ва сарфанишадани об таъсир мерасонад. Азбаски манбаъҳои оби маҳдуданд, системае, ки хангиш набошад, самаранокии баландтар дорад. Диққати ҷойгиркунӣ ба шустушӯи мунтазами ибтидо ва охирони ҳар як обёрӣ, идоракунии дақиқи фишор, филтррасонии бисёрбаробадӣ ва даргоҳкунӣ дар торикӣ, калиди асосӣ барои зиёд кардани умри тасмаҳои шумост. Ҳамеша дар хотир доред, ки тасмаи одумона абзорҳе аст; бо он бо хешмеҳнат муомила кунед то солҳои зиёд ба шумо хизмат кунад. Дар сурати зарурат ба роҳнамоии бештар дар бораи таҷҳизоти пайваст, шумо метавонед <a href="https://navar-abyari.ir/migdori-tukhi-rahatchulfa-dar-yek-hektar-dasturi-kisht/">Роҳнамоии парвариши майгӯ дар як гектар</a> ро ҳамчун намуна аз системҳои обёрӣи ҳассос дар фазои маҳдуд омӯзед, ҳолоки принсипҳои умумии идоракунии об монанданд.</p>','Интиқоли нури ТИП: Рӯйхати мукаммал барои беҳтар кардани обёрӣ бо усули қатрагӣ','Нигоҳубинии дуруст нӯри дриппер на танҳо ба шустани мӯҳим мерасад; он инчунин идоракунии фишор, филтратсия ва захиракунии фавсонаро дар бар мегирад. Дар ин мақола беҳтарин усулҳои муҳофизат аз сӯрохиҳои нозук нӯри дриппер ва баланд бардоштани самаранокии обӣкунӣ дар назар гирифта мешавад.','publish','closed','closed','intiqoli-nuri-tip-rahnemoyi-abori-qatragi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
