INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима ба парвариши петрушка ва зарурати истифодаи системҳои навини оварии об</h2>\n<p>Петрушка (Petroselinum crispum) яке аз гиёҳҳои баргӣ-sabziҳои маъмул аст, ки барои расидан ба сифат ва бадани муносиб ба рطубати доимӣ ва муносиб дар минтақаи реша ниёз дорад. Дар усулҳои анъанавии оварии оварии пашшӣ ё баронӣ, об мустақиман бо баргҳо муносбат мекунад, ки ғайр аз ин, муҳити намдорро барои паҳшӯрии бемориҳои қарзӣ ба вуҷуд меорад ва дар вақти ҳарӣ ба дағолҳои зард ва коҳиши арзиши тижорати маҳсулот меонад. Аз ҳамин сабаб, амалишавӣ <strong>оварии қатрагии петрушка</strong> ва системҳои наварии тип, як ҳалли донишмандона аст, на танҳо истифодаи обро то 30 фоиз кам мекунад, балки ростро мустақиман ғизо мекунад ва тозагии сатҳии маҳсулро кафолат мекунад. Дар ин мақола, тамоми андозаҳои техникӣ аз тайёри хок то ҷадвали таъмини овариро бо муфассал таҳқиқ мекунем, то ки деҳқонон бо эътимод аз маҳсулоти саломат ва пурфарован истифода баранд.</p>\n\n<h2>Интихоби беҳтарин усули кӯфтан ва ҷойгиркунии замин</h2>\n<h3>Фарқҳои асосии кӯфтани равиш ва нақши асоси хок</h3>\n<p>Пеш аз оғози ҳар як раванд, тайёрӣ ба асоси хок муҳимии ҳаёт дорад. Петрушка одатан дар равишҳои ду-тояфенак ё як-тояфенак парвариш мешавад, то ки имконияти гузариши таҷҳизот ва насби системаҳои оварии об осон карда шавад. Масофаи байни равишҳо бояд чунин бошад, ки ҷои кофӣ барои гузариши наварии тип ё қатрагиҳо вуҷуд дошта бошад. Стандарди тилоии масофаи байни равишҳо дар парвариши петрушка бо наварии тип, байни 40 то 50 сантиметр аст. Аз ҷониби дигар, масофаи байни бутунҳо дар як равиш бояд байни 10 то 15 сантиметр риоя шавад, то ки гиёҳҳо ҷои кофӣ барои нафаскашӣ ва ҷазби нур дошта бошанд. Риояи ин масофаҳо, рақобатро ба минимал мекунад ва потенсиали афзоиши ҳар бутунро ба қулла мерасонад.</p>\n<h3>Нақши системаҳои оварии об дар инкишофи решаҳо</h3>\n<p>Дар баъзи минтаҳоҳои гарм ва хушк, истифодаи <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%b2%db%8c%d8%b1-%d8%b3%d8%b7%d8%ad%db%8c-%da%af%db%8c%d8%a7%d9%87%d8%a7%d9%86/">обёрӣ зери сатҳи наботот</a> метавонад ивазкунандаи хеле мувофиқ бошад, зеро намӣро дар атрофи реша, дар рафъ аз хок нигоҳ медорад ва аз тавъбури шадид пешгирӣ мекунад. Аммо, дар аксарият боғҳои сабзеворӣ, қатори қариб (nibar-i tıp) бо сабаби маблағи кам, насби тез ва таъмири соддатар, вариантҳои иавзали ҳаруфчидани беговонон аст. Қатори қариб бояд дар рафъ аз сатҳи хок тақрибан 5 то 8 сантиэметр, дар наздикии хати кориз гузоранда бошад, то решаҳои ҷавони наботот аз лаҳзаи гузоштани беговонон дар тамоси рост бо қатори қариб бошанд ва обро ҷуброн кунанд.</p>\n\n<h2>техникаҳои пешрафтаи кориз ва барънамои амалиятҳо</h2>\n<h3>методҳои бехузи дилҳои кәриҷӣ</h3>\n<p>дилҳои кәриҷӣ бо сабаби пӯсти сахт, нисбатан дер нахӯрананд. Барои тез кардани раванди нахӯранда, тавсия дода мешавад, аз усули тамоми баҳорӣ (Cold Stratification) истифода бурд; ин маъно дорад, ки дилҳои кәриҷӣ дар пӯсти сард 1-2 рӯз нигоҳ доред, то ки пӯсти он ноҳаро дорад. Дар системаҳои муосири кишоварзӣ, машинаҳои шиларкушкӣ, ки имконияти коризи дилҳои кәриҷӣ ва қатори қарибро доранд, ҳарчарофӣ-барҳамбарииро меоранд. Ин ҳамзамонӣ боиси он мегард, ки баъзе мутақобилаи охири беговононон дар беговонони нахӯрандаи дилҳои кәриҷӣ ҷуброн карда шавад ва нопардонии бо сабаби дерии обёрӣ камтар шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-جعفری-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت جعفری با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои коризи дилҳои кәриҷӣ, обёрӣ бо қатори қариб, ҷадвали обёрӣ, кәриҷӣ</figcaption></figure>\n\n<ul>\n<li><strong>Коризи дастӣ:</strong> Барои боғҳои хурди хонагӣ ва боғҳои модарӣ алоиқом аст, вале ниёз ба диққати баланд дар таърифҳои ғарм ва фосилаҳои якхела дорад.</li>\n<li><strong>Кориши механизатсияшуда:</strong> Барои боруҳои таъҷироти масоҳати васеъ мувофиқ аст; кафолат медиҳад, ки паҳши донҳо ва насби чунҳои дрипс бо дақиқати баланд анҷом дода мешаванд.</li>\n</ul>\n<h3>Идоракунии наварчаҳои обӣ ва пешгирии зехиши ноустувор</h3>\n<p>Кориши пастазорӣ ҳосили ба зехиши зиёд нисбат ҳассос аст ва агар зехиш дарозмуддат бошад, решаҳо дорад пӯшиданро мегиранд. Бинобар ин, тарҳрезии наварчаҳои зехиши амиқ барои хориҷ кардани обҳои иловагӣ зарур аст. Шикофти замин бояд тақрибан аз 0,5 то 1 фоиз бошад, то ки обҳои иловагӣ зуд хориҷ гарданд. Унсурҳои фосилашавӣ, ки барои кориши пастазорӣ татбиқ мешаванд, дар андозаҳои хурд бо унсурҳои миқдори дони буғдолон дар ҳектар муқайёс намешаванд, зеро кориши пастазорӣ гиёҳи бунери хурд ва бунери ҳаракатнок аст, аммо аҳамияти мувозинат байни зичӣ ва обёрӣ дар ҳарду гиёҳ яксон аст.</p>\n\n<h2>Ҷадвали дақиқи барномаи обёрӣ дар марҳилаҳои гуногуни рӯшд</h2>\n<h3>Фурӯдат ва миқдори мувофиқи об дар ҳар марҳила</h3>\n<p>Барномакунии обёрӣ барои кориши пастазорӣ бояд асосан барои ҳаҷми нигоҳдории об дар хок (Field Capacity) муҳим бошад. Азбаски системаи решаи корехи пастазорӣ сатҳӣ аст, усули «кам ва такрор» ҳамеша самараноктар аз обӣҳои вазнин ва камбарор аст. Дар поён, ҷадвали ҷамъбасти барномаи обӣ барои ҳар марҳилаи рӯшд оварда шудааст:</p>\n<table border="1" cellpadding="5" cellspacing="0">\n<tr><th>Марҳаи рушд</th><th>Фосила байни оборӣ</th><th>Ҳаҷми об (миллиметр)</th><th>Маълумоти техникӣ</th></tr>\n<tr><td>Нӯл задан</td><td>Рӯзона (2 маротиба)</td><td>Аз 5 то 10</td><td>Нигаҳ доштани намии сатҳ барои кушодани пӯсти тоҳук ва гузаштан аз хок</td></tr>\n<tr><td>Сабзишҳои аввалин</td><td>Ҳар 2 то 3 рӯз</td><td>10 то 15</td><td>Зиричашавии тадриҷии чуқуршавии об бо густариши системаи реша</td></tr>\n<tr><td>Пайваставӣ ва афзоиш</td><td>Ҳар 2 рӯз</td><td>15 то 20</td><td>Омориш ҳаҷми зиёди барои пуштибони афзоиши тез ва барги пурҳаҷм</td></tr>\n<tr><td>Пухиш ва тайёркунии ҳосил</td><td>Ҳар 3 то 4 рӯз</td><td>10</td><td>Кам кардани рутубат барои зиёд шудани консентратсияи аҳроф, бӯй ва нигоҳ доштани сабзавии растанӣ</td></tr>\n</table>\n<p>Нуқтаи муҳим ин аст, ки чғҳзии ғӯфти баланд (миқдори зиёди бӯҳн) метавонад ба шиддати рақобати раҳоҳо барои об ва моддаҳои ғизоӣ таъсир расонад. Дар мунҳои бо чғҳзии зиёд, бояд нақшаи обёрӣро дақиқтар ва истифодаи зиёдтар идора кард, то нуқсоноти рутубат ҷуброн шавад. Ин принсип монанди принсипҳое аст, ки дар миқдори бӯҳни чав дар назар дошта мешавад, ҷоё мувозунат байни шумораи раҳоҳо ва манбағҳои об ҳайовӣ аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-جعفری-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت جعفری با آبیاری قطره‌ای - تصویر 2"/><figcaption>усулҳои ғӯфти қатқатӣ парвариши ҳосил нақшаи обёрӣ кунҷит</figcaption></figure>\n\n\n<h2>Нуқтаҳои асосӣ барои фоидаёбии ҳадди акс ва кам кардани хароҷотҳо</h2>\n<h3>Идоракунии зараррасонҳо ва бемориҳои хӯкистӣ</h3>\n<p>Як аз муҳимтарин бартарии истифодаи ленти ошорӣ хушк мондани сатҳи хок аст. Ин хосият монеи паҳншавии занҷирҳои зангҳои мӯяк ва хушкшавии сафед мешавад. Гарчанде ки ошории боронӣ дар боғҳои молифтони хӯраш ғаиб аст, вале барои пажӯст бояд <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%a8%d8%a7%d8%b1%d8%a7%d9%86%db%8c-%d8%b2%d9%85%db%8c%d9%86-%da%a9%d8%b4%d8%a7%d9%88%d8%b1%d8%b2%db%8c-%d9%88-%d8%aa%d8%a7%d8%ab%db%8c%d8%b1%d8%a7%d8%aa/">Ошории боронии замини кишоварӣ ва таъсири он</a> ро бо эҳтиёт таҳқиқ кард. Партофтан об ба баргҳои пажӯст боиси пайдои дағалҳои обзанишавӣ ва аҳволи нораҳматшавандаи маҳсулот мегардад, ки дар марҳилаи бахшидан ҳамчун камбуди хоси маҳсулот ҳисоб карда намешавад. Системаи ленти ошорӣ ин масъаларо аз асл ҳалли мешавад ва сифати зоҳирии маҳсулотно таъмин мекунад.</p>\n<h3>Тамъи ошорӣ (Fertigation)</h3>\n<p>Пажӯст растане аст, ки ба нитроген ҳаросияти баланд дорад. Илова кардани ҳавои NPK-и ҳалшаванда ба системаи ошори чуқуриқумарӣ таъмини ҷабби беҳтарини моддаҳои ғизоӣ мебошад. Аз помпуҳои таъминотӣ бо суръати танзимшаванда истифода баред, то таҳтишавии ҳаво вобаста ба марҳилаи афзоиш танзим шавад. Дар марҳилаи афзоиши вегетативӣ нитроген бештар лозим аст, аммо дар марҳилаи охирин бояд таъмини фосфорои ва калии баланд шуда, то таъми маҳсулот бозоритар шавад. Ин роҳ монанди принсипҳои ғизоёни дар <a href="https://navar-abyari.ir/comprehensive-pepper-drip-tape-guide-yield-tips/">Равнамаи васеи ленти ошории пипари болӣ</a> ҳаст, ки таъкид аз бойикунии об вобаста ба ниёзи махсуси растанӣ дорад.</p>\n\n<h2>Ҷавоб ба саволҳои асосии кишоварон (FAQ)</h2>\n<h3>Оё байни бастони паҳлоии (тип) ва қатқаттаки дар парвариши шпинат фарқе вуҷуд дорад?</h3>\n<p>Бастони паҳлоӣ одатан арзонишрои камтар дорад ва барои саҳҳулҳо бо сатҳҳои дароз хеле мувофиқ аст. Аммо қатқаткаҳои ҷудо (дроп) дар тақсимоти об дақиқтари бештар доранд ва барои саҳҳулҳои хурд бо тарҳи мушаххас метавонанд интихоби беҳтарин бошанд. Барои шпинат бо зичии ғайриоддӣ, бастони паҳлоӣ бо пухиши давраии найҳо корҳои хеле хуб дорад. Инчунин барои дидани нархҳо ва раҳнамоии харид, мақола <a href="https://navar-abyari.ir/lf-pipe-price-guide-iraq/">Пайванди нархҳои найҳои Лав (LF)</a> -ро омӯзед, то беҳтарин интихоби иқтисодиеро тахия кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-جعفری-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت جعفری با آبیاری قطره‌ای - تصویر 3"/><figcaption>усулҳои нигоҳдорӣ қатқатка парвариши ҳосил вақтҷадвали обгӣ шпинат</figcaption></figure>\n\n<h3>Оё истифодаи системаҳои қадимии обгӣ бо боронӣ воқеан мумкин аст?</h3>\n<p>Истифодаи усулҳои анъанавии монанд <a href="https://navar-abyari.ir/foydahoi-nvori-tipii-obyri-tarafduzi/">фоиданураи бастони паҳлоии обгӣ бо сурати якҷониба</a> Усули, ки ҳоло бештар истеъмол шудааст, имрӯз камтар тавсия дода мешавад, магарак дар шароити махсус. Системаҳои қатра ва стрипҳои намоишӣ ҳамеша интихоби беҳтарин барои нигоҳ доштани баргҳо хушк, кам кардани буғшавӣ ва зиёд кардани самаранокии ниҳоӣ мебошанд. Агар боиси муқоиса бо дигар растаниҳо, масалан бобакҳои сабз ё қибош, хоҳед, фарқияти самаранокӣ-ро санҷед.</p>\n\n<h2>Хулосаи ниҳоӣ ва тавсияҳои охирин</h2>\n<p>Амалӣ кардани дуруст <strong>Обиёрӣ-и қатраи сабзавот</strong> Ва системаҳои стрипи намоишӣ тағйироти решагирифтарро дар иқтисодиёти боғзорҳои сабзавот меоварад. Бо риояи дақиқи ҷадвали барқароркунӣ пешниҳодшуда, нигоҳ доштани фосилаҳои стандартӣ барои ғармакунии ғунчаҳо ва таваҷҷуҳ ба парвариш бо об (Fertigation), шумо метавонед мавлиди тоза, саломат, боиҳро ва сифатнокро бо истифодаи оптималии манбаъҳои об ба даст оваред. Ба деҳқонҳо тавсия мешавад, ки ҳамеша аз таҷҳизоти сифатнок истифода баранд ва бунёди боғзорро мувофиқи шароити иқлимии минтақашон шахсӣ созанд.</p>','Равиёи мукаммал ва ихтисосии парвариши корзи бо истифода аз системаҳои обёрӣ бо банду бандҳо ва наворҳои ипий','Зайфиб (замирӣ) ашъор аст, ки ба намӣ ҳассос аст ва бо идоракунии дурусти оборӣ тавассути қатрадорӣ ва системаи нибҳар, метавонад ба баландтарин самаранокии хос расад. Ин дастрас принсипҳои карзнокӣ, тақвими тартибот ва нуқтаҳои калидии афзоиши самаранокӣро мебахшад.','publish','closed','closed','ravoyi-parevarishi-korz-o-sistema-yob-berii-bandbandho',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
