INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти идоракунии дурусти зичии ғарсонии соя</h2>\n<p>Соя яке аз муҳимтарин дарахтҳои дунё аст, ки аз сабаби паротеини баланд ва равғони бой, ҷойгоҳи махсусро дар парҳези инсон ва чорво ёфтааст. Аммо барои расидан ба самаранокии иқтисодӣ, дарки дақиқ <strong> миқдори тоқи соя дар гектар</strong> як параметри ҷонбахш аст. Бисёр деҳқонон ба эътимод меоранд, ки ҳар қадар тоқи бештар бичинанд, ҳосили зиёдтар хоҳанд дошт, аммо ин хатои арзандаст. Зичии зиёд ба рақобати дарахтон барои нур, об ва моддаҳои ғизоӣ мусоидат мекунад ва дар натиҷа ба кам шудани андозаи дониҳо ва ҳатто заҳол шудани дарахтони заиф оварда мерасонад. Аз ҷониби дигар, зичии кам маънои истифодаи самаранок набудани замин ва кам шудани ҳосили умумиро дорад.</p>\n<p>Дар ин раҳнам, мо на танҳо ба рақамҳо ва меъёрҳои стандартӣ мегузарем, балки бознигарӣ мекунем, ки чӣ гуна тағйирёбандаҳои дигар монанди намуди тоқи, сифати тоқи ва системаи обёрӣ ба ин миқдор таъсир мерасонанд. Ҳамчунин ба бахшҳои махсусӣ монанди масоҳати байни сатҳҳо ва дар сатҳҳо диққат дода мешавад, то шумо метавонед нақшаи дақиқи ғарсонӣ (Precsion Planting)-ро иҷро кунед.</p>\n\n\n\n<h2>Параметрҳои калидии ҳисоб кардани миқдори тоқи соя дар гектар</h2>\n<p>Барои муайян кардани миқдори тоқи лозима, нобоядаст, ки як рақами собитаро барои ҳамаи иқлимҳо дар назар гиред. Омили зиёде ба ин миқдор таъсир мерасонанд. Мухимтарин омил, масоҳати ғарсонист. Стандартҳои маъмули ғарсонии соя одатан дорои масоҳатҳои 30, 40 ва 50 сантиметр дар сатҳ ва 60 то 70 сантиметр байни сатҳҳо мебошад.</p>\n\n<h3>Таъсири фоизи саросарӣ ва энергиягирӣи тоқи</h3>\n<p>Пеш аз ҳар ченукунии муайяншуда, бояд <strong>садди анвои бовк</strong> ва <strong>энергияҳои бовк</strong> онро санҷед. Бовки соя умри захиравии кӯтоҳ дорад ва қобилияти намоиш доштанаш бо мусоиди вақт кам мешавад. Агар энергияи бовки шумо 95 фоиз бошад, ғайр аз бовки тозе бо энергияи 99 фоиз, эҳтимолан ниёз ба зиёд кардани миқдори бовк хоҳед дошт. Инчунин андозаи дон будани бовк низ нақш дорад; донҳои калонтар одатан дар ҳар килограм шумораи камтар доранд.</p>\n\n<h3>Формулаи ченкунии тахминӣ</h3>\n<p>Барои ҳисоб кардани миқдори бовки соя дар ҳектар, шумо метавонед аз логикаи мураба истифода баред. Мисолан, бо фарз фосилаи 30 сантиметр дохили сатр ва 60 сантиметр байни сатрҳо, андозаи растаи пухта тақрибан 150,000 то 200,000 раста дар ҳектар хоҳад буд. Бо фарз он ки ҳар килограм бовк тақрибан 1200 то 1500 дон дорад ва дар назар гирифтани омилҳои нуқсон (Loss Factor) тақрибан 10 то 15 фоиз, ниҳоӣ миқдор одатан дар маҷмуаи 100 то 150 килограм дар ҳектар қарор мегирад. Албатта, ин рақамҳо вобаста ба иқлим ва ҳадафи шумо (дон ё консерв) тағйир меёбанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سویا-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر سویا در هکتار: راهنمای جامع - تصویر 1"/><figcaption>суръати бовк дар ҳектари маводи соя</figcaption></figure>\n\n<table border="1" style="width:100%; border-collapse: collapse;">\n  <thead>\n    <tr>\n      <th>Фосилаи ниҳол (сантиметр)</th>\n      <th>Миқдори тавсияшуда (рӯйхона/ектар)</th>\n      <th>Миқдори тахминии бех (килограм/ектар)</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>30 x 60</td>\n      <td>166,666</td>\n      <td>110 - 130</td>\n    </tr>\n    <tr>\n      <td>40 x 70</td>\n      <td>135,714</td>\n      <td>90 - 110</td>\n    </tr>\n    <tr>\n      <td>50 x 80</td>\n      <td>125 000</td>\n      <td>80 - 100</td>\n    </tr>\n  </tbody>\n</table>\n\n<p>Лут зарб доред, ки ин рақамҳо қиматҳои назаҳӣ мебошанд. Дар амал, ҳамеша тавсия мешавад, ки барои ҷобур кардани фосилаҳое, ки бо машинаи бозӣ (бозидорӣ) ба вуҷуд меоянд, миқдоре зиёдтар истифода баред, то зичии якхела ба даст ояд. Барои маълумоти бештар дар бораи интихоби беҳтарин бӯри мувофиқ ба иқлимҳои минтақаи шумо, метавонед роҳнамои <a href="https://navar-abyari.ir/mung-bean-seed-amount-per-hectare/">Миқдори бӯри бобои чашм-булӯбӣ</a> -ро омӯзед, чунки принсипҳои зичии он ба соя монандиҳо дорад.</p>\n\n\n\n<h2>Нақши системаи обёрёнии қатъагӣ ва навори тип дар кунҷовии соя</h2>\n<p>Алоқаи байни зичии натики дӯкон ва системаи овароши об бисёр пухта аст. Вақте ки аз системаи овароши об зерофи фишор истифода мебаред, ҷойгиркунӣ (Layout) хати обришӣ бояд бо хати нагунҳои кӯшодан мувофиқ бошад, то тобиҳо баро об ва моддаҳои иловагӣ ба таври якхела пайдо кунанд.</p>\n\n<h3>Чаро нави Тиб варианти беҳтар аст?</h3>\n<p>Дар парвариши соя, истифодаи нави Тиб дар нагунҳои дуқта ва блокӣ одатан самаранӯки баландтар дорад нисбат ба нагунҳои оддӣ. Нави Тиб боиси пайдо шудани нӯҳеи тӯлӣ дар роҳи тобиҳо мекунад. Ин хусусият барои кӯшоданҳоеро ки тобиҳои сатҳӣ доранд ва барои овароши об бо миқдори кам бисёр зарурат доранд, идеалӣ аст. Инчунин, нави Тиб даватноки баландтар нисбати илтибои тобиҳо дар заминҳои ғарғурӣ дорад.</p>\n\n<h3>Траккунашавии овароши об зерозии ва нагунҳои дақиқ</h3>\n<p>Яке аз пештарин усулҳо, истифода аз <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%b2%db%8c%d8%b1-%d8%b3%d8%b7%d8%ad%db%8c-%da%af%db%8c%d8%a7%d9%87%d8%a7%d9%86/">овароши об ба кӯшоданҳои зерозӣ</a> аст. Дар ин усул, об ба ҷои сатҳи замин, дар чукур тақрибан аз 10 то 15 сантиметр мепардозанд. Ин кор боиси он мешавад, ки сохтори сатҳи замин нигоҳ дошта мешавад ва аз буғшавии бевоситаи об пешгирӣ мекунад. Барои соя, ки барои марҳилаҳои ҳосили ғаҳвонаи росткунӣ зарурати беш дорад, ин усул метавонад фарқи калонро дар сифати гулони пайдо кунад. Аммо нуқтаи муҳим ин аст, ки чукураи нагун бояд бо чукураи хуруҷи нӯҳеи об мувофиқ бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سویا-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر سویا در هکتار: راهنمای جامع - تصویر 2"/><figcaption>miqdor koshish ba hectare soyabonyatsoy</figcaption></figure>\n\n<h2>Нуқтаҳои амалӣ барои беҳтар карди ҷамъоварӣ ва обёрӣ</h2>\n<ol>\n  <li><strong>Мусоидати хатҳо:</strong> Хатҳои навози хӯрокиро ва парҳезро беҳтар дар самти шимол-ҷанубӣ ё шарқ-ғарбӣ ҷойгир кунед, то ки таъсири саргирии гуногони баъзе ҳадд ба ҳадди ақал баррасӣ шавад. Самти саргири метавонад ба миқёи метри беҳтар таъсири расонад.</li>\n  <li><strong>Санҷиши фишори об:</strong> Пеш аз ҷамъоварӣ, дар вақти истифодаи обёрӣ бо навози хӯрокӣ ба нуқтаҳои муҳим диққат диҳед. Муқаррарӣ фишори об метавонад ба хушкшавии баъзе минтаҳо ва куҷи ашъони сабуки сабаб шавад.</li>\n  <li><strong>Дастгирӣ аз гиёҳони бегона:</strong> Бархӯрд ғизои сабук метавонад ба шудан гиёҳ ба дастгирӣ бо гиёҳони бегона сабаб кунад, вале наметавонад ба миқдор чунин зиёд шавад, ки чармоғӣ ва парҳез пас аз парҳез осон набошад. Аз омезиши гиёҳкӯшандаҳо пеш аз ҷамъоварӣ ва пас аз ҷамъоварӣ истифода баред.</li>\n</ol>\n\n<p>Ҳамчунин дар интихоби қисмҳои системаи обёрӣ, диққат ба қаллоқии дивор муҳим аст. Интихоби навози хӯроки аз маводи мувофиқ ва бар зидди нури офтоб таъсиранда ба умри системаи дарозтар мусоидат мекунад. Дар бораи қаллоқии стандартӣ навози хӯрокӣ омӯзед, то муболиғаи дастгирӣ аз хариди абзорҳои давомноки мувофиқ бошад.</p>\n\n\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё ман метавонам бӯди сояро дар хокӣ хунук кунем?</h3>\n<p>Соя растании тақсимшуда ба гармӣ аст. Партов кардани китоб дар хок дар сард ба кам кардани қобилияти барор овардан ва зиёдшавии бемориҳои зараррасон меорад. Агар шумо маҷбур бошед дар хок дар сард кунад, бояд <strong>Масоҳати бӯди соя дар як гектар</strong> ро тақрибан 10 то 15 фоиз зиёд кунед, то инки аз пӯшидани сӯрохҳое, ки аз ҳал шудани китоб ба вуҷуд меояд, пешгирӣ шавад.</p>\n<h3>Кадом масофа барои партов кардани сояи деим мувофиқ аст?</h3>\n<p>Дар партови деим, бо сабаби маҳдудиятҳо дар манбаъҳои об, масофа бояд аз ҳолати партов бо қатра-обкунӣ камтар бошад. Одатан масофа байни хатҳо зиёд мешавад. Барои маълумоти бештар дар бораи принсипҳои умумии партови деим ва тақозаҳои об, шумо метавонед ба саҳифа <a href="https://navar-abyari.ir/detailed-cucumber-drip-irrigation-guide/">Раҳнамои умумии қатра-обкунӣ</a> Боварӣ ҳосил кунед, ки таърихи умумии идоракунии обро менамояд.</p>\n<h3>Оё истифодаи системаи орошавии қатъоӣ ба тоҳи бузургтарин таъсир мерасонад?</h3>\n<p>Бале, андозаи тоҳи соя, ки одатан аз гӯгӯк ё чӯппон калон аст, ба чоргоҳи муносиб дар корҳои тоҳкунӣ ниёз дорад. Агар чуҳари тоҳкорӣ муносиб набошад, қатъоҳо метавонанд ба тоҳ бархӯранд ва онро парторанд ё сабаби пайдо шудани холигӣ даваранни тоҳ гарданд, ки ба хушк шудани тоҳ оварда мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سویا-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر سویا در هکتار: راهنمای جامع - تصویر 3"/><figcaption>norma посева на гектар соя</figcaption></figure>\n\n<h2>Хулоса ва натиҷаҳои ниҳоӣ</h2>\n<p>Муайянсозии дақиқ <strong>Миллати тоҳи соя дар ҳектар</strong> Ин омехтаи дониши зичии рӯёноӣ, сифати тоҳ ва идоракунии манбаъҳои об мебошад. Истифодаи системҳои орошавии дақиқ, ба монанди системаи қатъоӣ, на танҳо ба сарфаи истифодаи об менамояд, балки ба шумо имкон медиҳад, ки бо зичии мувозинатшуда кор кунед. Бе диладориву эзоҳ нест, ки ҳар як килограмми камтари тоҳ, ки партобарӣ мекунед, хароҷотро кам мекунад, аммо бе диладориву эзоҳ нест, ки зичии хеле паст самаранокии умумии земакро вайрон мекунад.</p>\n<p>Тавсияи ниҳоии мо ин аст, ки пеш аз оғози мавсими кишоварӣ, дар як қисми 10 метрӣ бо ду андозаи гуногун (масалан, кам ва зиёд) як таҷрибаи хурд иҷро кунед ва дар охири мавсим, ҳосили ҳар қисмро муқоиса намоед. Ин усул роҳи илмитарин барои ёфтани "нуқтаи муносиб" барои лӯбишумак дар деҳона шумо аст. Бо риояи асосҳои кариши дақиқ ва обёробии идорашуда, шумо метавонед ба ҳосили рақобатӣ ва устувор ноил шавед.</p>\n<p><strong>Мавзӯи робитагӣ:</strong> <a href="https://navar-abyari.ir/%D8%AA%D9%81%D8%A7%D9%88%D8%AA-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A8%D8%BA%D9%84-%D8%AF%D9%88%D8%AE%D8%AA-%D9%88-%D9%BE%D9%84%D8%A7%DA%A9%D8%AF%D8%A7%D8%B1/">D8AAD981D8A7D988D8AA D986D988D8A7D8B1 D8AADB8CD9BE D8A8D8BAD984 D8AFD988D8AED8AA D988 D9BED984D8A7DAA9D8AFD8A7D8B1</a></p>','Микдори навутҳои соя дар як гектар: Роҳнамои пурраи кишт ва обкорӣ','Дар ин мақолаи мукаммал, мо дақиқтарин усулҳои муайян намудани миқдори буби соя дар ҳектарро баррасӣ мекунем. Ин раҳнамоии амалӣ нуқтаҳои бунёди бобунбоқи соявиро мувофиқи шароити иқлим ва ҳилолҳои обии қатрагоронро барои деҳқонони арҷманд шарҳ медиҳад, то сармоягузории бозори муносибтар бошанд.','publish','closed','closed','mikdori-navuti-soya-har-gektar-kisht-obkori',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
