INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Дар системаҳои оварии тамқулӣ (дропӣ), <strong>масофаи расидан (тип) дар коркиши зардоб</strong> яке аз унсурҳои асосии муҳандисии обёрӣ буда, бевосита ба сифати ғӯлори намнок (Wetting Front) ва дар натиҷа ба афзоиши якбораи сагҳо ва решаҳои зардоб таъсир мерасонад. Бисёр кишоварзон ин масофаро танҳо дар асоси шухӯр ё бе назардошти омилҳои гидроликӣ интихоб мекунанд, гарчанде ки бехтарсозии ин параметр метавонад ба кам шудани талафоти об, пешгирии бемории қаҳваранги реша ва зиёдшавии ҳаҷми решаҳои савдоӣ оварда расонад. Дар ин қисм мо ба таҳлили муфассали принсипҳои фаннӣ ва маслиҳатҳои амалӣ мепароем.</p>\n<h2>Назарияҳо ва асосҳои бодирии даропӣ барои зардоб</h2>\n<p>Зардоб растаниест, ки решаҳои захиравии он амиқраванд ва ба тақсими якбораи намнокӣ дар мингои решагирӣ ҳассосияти баланд доранд. Расидан (Drip Tape) аз сабаби қобилияти иҳром намодани об бо дебити паст, вариантҳои идеалӣ барои ин растани аст, вале агар масофаи расидан аз хати нишаст ё аз расиданҳои муҳорири номувофиқ бошад, «нуқтаҳои хушк» ё «намнокӣ зиёдтар» вujud меоянд. Мақсади танзими масофаи расидан дар коркиши зардоб, эҷоди як <em>ғӯлори намнок</em> доимӣ (Overlap) аст, ки тамоми ҳаҷми хокӣ-ресаваро пурнамекунад.</p>\n<ul>\n<li><strong>Амқи решагирӣи зардоб:</strong> Ододар 30 то 50 сантиметр; бинобар ин, шитро бояд дар омор таъйин шавад, ки об зуд ба чуқурӣ наравад ва парҳези мубалғаи об аз минтақаи решаҳо ҳодиса нашуда бошад.</li>\n<li><strong>Фарос ва суръати ҷорӣ:</strong> Суръати ҷории чанчунҳои шитробояд мувофиқи масофаи лоҳиҷасозӣ интихоб шавад, то суръати паҳншавии об аз сатҳи решагирӣ гузаранда нашуда бошад.</li>\n<li><strong>Тарҳии тарафии решаҳо:</strong> Решаҳои шарбатӣ дар ҳолати камбудии тар, ба сӯи хушкӣ меоянд, ки ин ба тағйири шакли реша ва сустии афзоиш оварда мерасонад; бинобар ин, масофаи шитро бояд имконияти пайдо шудани ин дурӯдии тарроҳиро диҳад.</li>\n</ul>\n<p>Дар лоҳиҷасозии ҷойгиркунӣ, ду сенарияи асосӣ вуҷуд доранд: <strong>Ҷойгиркунии як шитро</strong> (як шитро дар миёнаи силсила) ва <strong>Фекрибшории дуқутъатӣ</strong> (ду навои бо фосила аз маркази қатор). Барои чарогоҳи тиҷоратӣ, ба сабаби шакли силиндриҳои ва ҳассосияти решаҳо ба фишори хок ва намнокии ноумуми, фекрибшорҳои махсус тавсия мешаванд, ки дар поён шарҳ дода мешаванд.</p>\n\n\n\n<h2>Стандартҳои техникии фосилаи навои чарогоҳ барои парҳези чарогоҳ</h2>\n<h3>Таъсири фосилаи нав бар якгонагии намнокӣ</h3>\n<p>Фосилаи навои чарогоҳ дар парҳези чарогоҳ ба таври стандартии ба чанд параметр вобаста аст: ноди хок, қудрати қуттаанӣ ва диаметри расоии лозимаи решаҳо. Дар хокҳои гилӣ, суръати фурӯбарии об паст аст ва фосилаи нав аз хати кишт бояд камтар бошад, то аз хушк шудани сатҳи бистри пешгирӣ шавад. Дар нобоҳонӣ, дар хокҳои рӣшандорӣ, фурӯбарии тез аст ва метавон фосиларо каме зиёд кард, то энергияи сарфшуда ба фурӯбарии чуқур кам шаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-هویج-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت هویج: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop чарогоҳ</figcaption></figure>\n<p><strong>Тавсияҳои андозагӣ:</strong> Фосилаи оддии навои чарогоҳ аз хати кишти чарогоҳ байни <strong>15 то 20 см</strong> барои ҳарду тараф тавсия мешавад. Азбасби истифодаи наварҳои дуқутрӣ, фосилаи байни ду навар тақрибан <strong>40 то 50 см</strong> (вобаста ба андозаи қадди) танзим карда мешавад. Ин андозаҳо ба он таъсир мерасонанд, ки ду ҳалқаи обшуда аз ду тарафи навар дар маркази қадд, ҷое ки решаи асосӣ ҷойгир аст, муттаҳид (Merge) шаванд. Агар фосила хеле зиёд бошад, як <em>ҳудуди намдоданида</em> дар маркази қадд боқӣ мемонад, ки решаҳои асосӣ дар он ҷой хушк мемонанд. Агар фосила хеле кам бошад, консентратсияи намӣ дар сатҳи реша метавонад боиси вайроншӣ ва бемориҳои қаҳрагӣ гардад.</p>\n\n<h3>Нақши суръати равонии қатраандоз дар муайян кардани фосила</h3>\n<p>Фосилаи навар ва суръати равонии қатраандоз робитаи мустақиме бо ҳам доранд. Дар ҷадвали зерин, таъсири мутақобилаи ин ду параметр ба ҳар қисми тарҳи натила нишон дода шудааст. Интихоби як суръати стандартӣ мисли 1/6 ё 1/8 литр дар соат дар наварҳои типис, ба танзими дақиқи фосила ниёз дорад, то суръати ҷоригии об ба амиқӣ бо суръати рушди решаҳо ҳомангум шавад.</p>\n<table border="1" cellpadding="5">\n<tr><th>Навъи хок</th><th>Диққати шитоби нӯри (Л/со)</th><th>Фосилаи нӯри аз хати кунд</th><th>Шарҳ</th></tr>\n<tr><td>Рехи оҳиста</td><td>1/6 - 1/8</td><td>12 - 15 сантиметр</td><td>Ҷубори кам; барои пуркунии беҳтар сатҳ наздикӣ лозим аст</td></tr>\n<tr><td>ломи-росӣ</td><td>1/4</td><td>15-20 сантиметр</td><td>тамоми байни ғулубии амиқ ва паҳлӯӣ</td></tr>\n<tr><td>ломи-шино</td><td>1/2</td><td>20-25 сантиметр</td><td>ғулуби тез; имконияти зиёд кардани фосилаи миён, бе хушкшавии марказ</td></tr>\n</table>\n\n<p>Барои беҳтар фаҳмидани рафтори намӣ дар ин шароит, лоиҳакашии миқдори обии нахи обёркунии тамғаӣ ҳамчун меъёри аввалина зарур аст, зеро фосилаи нах бе шиносӣ бо миқдори воқеии обии нах дар заҳми худ имконпазир нест.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-هویج-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت هویج: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>Фосилаи нахҳои тамғаӣ Ҷойгирӣи сатҳи сабзавот Тилбос</figcaption></figure>\n\n\n\n<h2>Нуқтаҳои амалӣ ва иҷроӣ дар заминҳои тилбос</h2>\n<h3>Роҳнамои қадам ба қадам барои танзими ҷойгирӣ</h3>\n<ol>\n<li><strong>Ченаки андозаи сатҳи:</strong> Пеш аз насби нах, андозаи сатҳи тилбосро бо дақиқӣ муайян кунед. Фосила байни ду сатҳи ҳамсоя бояд чунин бошад, ки фосилаи нах (аз нах то нах) ҳамвор ва мантиқӣ бошад.</li>\n<li><strong>Насби нах дар болои заҳми:</strong> Нахҳои тамғаӣ дар кӯтӯҳии тилбос одатан дар болои заҳм ё то баландии 5 сантиметр дар поёни заҳм ҷойгир карда мешаванд, то намӣ зуд ба минтақаи реша барсад ва парокандашавии бефоидаи амиқ пешгири шавад.</li>\n<li><strong>Истифодаи сенсорҳои намдӯхӣ:</strong> Пеш аз муайян кардани масофа, барои шинохтани нуқтаи пайвастшавии ҳалқаи босмоғ (аз ду пояндак) сенсорҳои намдӯхии хокро дар амиқи 10, 20 ва 30 сантиметрӣ истифода баред. Мақсад ин аст, ки дар амиқи 20 сантиметрӣ намдӯхӣ аз сарҳади хушкӣ гузарад.</li>\n<li><strong>Паҳлӯи пешгирии даромудагӣ:</strong> Масофаи кам миёнаи пояндак ва реша боиси он мегардад, ки ришакҳо метавонанд ба чорхӯрди пояндак бимоманд; бинобар ин, масофаи стандартӣ (камтар аз 15 сантиметр) аз пайвастшавии беваситаи системаи реша бо сатҳи пояндак пешгирӣ мекунад ва ниёз ба шустани давравии пояндакро кам мекунад. Барои маълумоти беш дар ин соҳа, бахши нигоҳубини пояндаки тиббӣ ва хароҷотҳоро омӯзед.</li>\n</ol>\n\n<h3>Таъсири он ба ҳосил ва сифати тиҷоратӣ</h3>\n<p>Тағйири масофаи пояндаки тиббӣ дар кишти турп, на танҳо як параметри обёрӣ аст, балки бевасита ба <em>шакли зоҳирӣ</em> решаҳои тиҷоратӣ таъсир мерасонад. Решаҳое, ки дар муҳити хушк рушд мекунанд, кӯтоҳтар, буримон ва бо сатҳи бозғор аст. Дар ҳоле ки ҳалқаи босмоғи якхела аз масофаи стандартӣ боиси он мегардад, ки реша бо суръати устувор дар амиқӣ рушд кунад ва сатҳи ҳамвор ва фурӯшпазим дошта бошад. Инчунин, паҳншавии дурусти намдӯхӣ аз рушди буқъаҳои иловагӣ ва решаҳои икунанӣ пешгирӣ мекунад, ки ҳаҷми решаи асосиро таъсир мерасонанд. Ин масъала барои кӯҳинарони, ки ҷустуҷӯи самаранокии баландтаринро доранд, муҳим аст. Барои муқоиса бо дигар маҳсулоти решагӣ, шумо метавонед роҳнамои <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A8%D8%A7%D8%AF%D9%85%D8%AC%D8%A7%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" target="_blank">Миқдори бодири лӯбиёи ҷаҳонӣ дар ҳектар</a> ро таҳқиқ кунед, то муҳимии ҳаракаткунӣи системҳои обёрӣро дар кишти решаҳои гуногун дарк кунед.</p>\n\n\n\n<h2>Ҷавоб ба саволҳои маъмул</h2>\n<h3>Саволи 1: Оё фосилаи наварии нақшабардор дар кишти сёббарӣ барои ҳамаи марҳилаҳои рӯйшуд якхела аст?</h3>\n<p>Нах, ниёз ба намнокии сёббарӣ дар марҳилаҳои гуногун фарқ мекунад. Дар марҳилаи аввалини рӯйшуд (1 то 2 ҳафта), решаҳо несттар буда, ҳассосият ба фишори намнокии баландтар аст; бинобар ин, фосилаи наварро каме камтар (тақрибан 15 сантиметр) нигоҳ доред, то намнокии сатҳӣ баландтар бошад. Дар марҳилаҳои рӯйшуди тез (маҳи дуюм баъд), метавон фосиларо то ҳадди иҷозат зиёд кард ва сарро баръёси рӯйшуди реша мувофиқат кард.</p>\n\n<h3>Саволи 2: Ҳангоми истифодаи партошҳои пластикӣ (моуч) чӣ тағйирот дар фосила медеҳад?</h3>\n<p>Истифодаи моуч боиси зиёд шудани суръати дохилшавии об дар заминҳои вазнин мебошад. Дар ин ҳолат, фосилаи навар аз хати кишт то 2 сантиметр зиёд шуда метавонад, зеро энергияи дохилии чуқуртар аст. Аммо ҳатман бояд намнокии сатҳи замин болои решаҳои нестро фаромӯш накунед; агар решаҳо болои моуч бошанд, фосиларо камтар баррасӣ кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-هویج-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت هویج: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop сёббарӣ</figcaption></figure>\n\n<h3>Саволи 3: Агар решаҳои картошка ба нақраи дарад оварданишӯ (drip line) расанд, бояд чӣ кор кард?</h3>\n<p>Сабукӣ (тастидкунӣ) реша (Root Hardening) ба нақраи дарад оварданишӯ метавонад ба шикастани шинақҳо ва ғайритабии минтақаҳои муқобил оварда расонад. Барои пешгирӣ, барои нақра аз муҳофизати реша (паҳлӯи хок фишурдашуда) истифода барад ва масофаи нақраро ҳадди ақал 10 сантиметр аз маркази решаи асосӣ нигоҳ доред. Инчунин, барои пешгирӣ аз ҷамъшавии зарраҳои хурд дар ҷои пайвастшавии реша ва нақра, истифодаи филтрасияи чанд марҳилаӣ тавсия дода мешавад. Барои идоракунии беҳтари система, ба иттилооти миқдори обии нақраи дарад оварданишӯ (drip irrigation) муроҷиат кардан, ба танзими фишор ва кам кардани фишори решаҳо ба нақра имкон медиҳад.</p>\n\n<h2>Хулоса ва тавсияҳои охирин</h2>\n<p>Оптимизатсия <strong>Масофаи нақраи дарад оварданишӯ дар кӯри картошка</strong> Ин як раванди динамикӣ аст, ки бояд асоси шароитҳои ҳар як боғ (қобилияти хок, иқлим ва ҳатто усули кӯрӣ) ҷудокунӣ шавад. Бояд, принсипҳои асосӣ, ки онҳо нигоҳ доштани як халқаи таркилшудаи пайваст, пешгирӣ аз хушкӣ маркази сатриҳо ва нигоҳ доштани масофаи стандартӣ 15 то 25 сантиметр аз хати кӯриш, ҳамеша дурустанд. Пайравӣ ба ин меъёрҳо на танҳо хуруҷи обро кам мекунад, балки бо беҳтар шудани сифати визуалии реша, қимати тиҷоратии маҳсулро ба таври иқтибос меафзояд. Тавсия дода мешавад, ки дар ҳар мавсими кишоварзӣ, аз ҳисобкунии рақамии ғафсишиҳо истифода барад, то рафтори воқеии ғафсишиҳо дар минтақаи решакишонӣ бевосита назорат карда шавад. Инчунин, барои фаҳмиши беҳтари динамикаи ғафсишиҳо ва тарҳрезии система, тадқиқоти миқдори обии нақраи дарад оварданишӯ (drip irrigation) ҳамчун манбаи асосӣ дар ҳисоботи муҳандисӣ хеле муфид мебошад.</p>\n<p><strong>Мавзӯъҳои пайваста:</strong> <a href="https://navar-abyari.ir/canola-yield-per-hectare-guide-iraqi-farmers/">canola yield per hectare guide iraqi farmers</a>， <a href="https://navar-abyari.ir/%d9%86%da%af%d9%87%d8%af%d8%a7%d8%b1%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d9%88-%d9%87%d8%b2%db%8c%d9%86%d9%87/">Нигоҳубинии навори тиби ва хароҷотҳо</a>, <a href="https://navar-abyari.ir/mohdath-intaj-thur-maksikhi-li-l-hektar-daleel-shamil-lil-muzariin/">mohdath intaj thur maksikhi li l hektar daleel shamil lil muzariin</a></p>','Фосилаи пайдори карбона дар кундшавии карбон: Стандартҳои тавсияшуда','Интихоби фосилаи мувофиқи намунаи пуршавии нақши муҳимро дар солим будани реша, самаранокии об ва зиёд шудани ҳаҷми ҳосил боз мекунад. Ин роҳнамои амалӣ меъёрҳои техникии ва нуқтаҳои иҷроӣ барои тарҳрезии дурусти қатқатро шарҳ медиҳад.','publish','closed','closed','farasoni-karmoni-karbashivi-karbon',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
